import React, { useEffect, useMemo, useState } from "react";

const DEFAULT_WATCHLIST_PREFIX = "Watchlist";

function formatNumber(value) {
  return value.toLocaleString("en-IN", { maximumFractionDigits: 2 });
}

function formatChange(value) {
  const prefix = value > 0 ? "+" : "";
  return `${prefix}${value.toFixed(2)}%`;
}

function getTrend(value) {
  return value >= 0 ? "up" : "down";
}

export default function Watchlist({
  watchlists,
  activeWatchlistId,
  selectedSymbol,
  filterQuery,
  onSwitchWatchlist,
  onAddWatchlist,
  onRenameWatchlist,
  onAddSymbol,
  onRemoveSymbol,
  onSelectSymbol,
  getStockBySymbol,
}) {
  const [newWatchlistName, setNewWatchlistName] = useState("");
  const [renameValue, setRenameValue] = useState("");
  const [newSymbol, setNewSymbol] = useState("");

  const activeWatchlist = useMemo(
    () => watchlists.find((list) => list.id === activeWatchlistId),
    [watchlists, activeWatchlistId]
  );

  useEffect(() => {
    setRenameValue(activeWatchlist?.name ?? "");
  }, [activeWatchlist]);

  const filteredSymbols = useMemo(() => {
    if (!activeWatchlist) return [];
    const normalized = filterQuery.trim().toUpperCase();
    if (!normalized) return activeWatchlist.symbols;
    return activeWatchlist.symbols.filter((symbol) =>
      symbol.toUpperCase().includes(normalized)
    );
  }, [activeWatchlist, filterQuery]);

  const nextDefaultWatchlistName = useMemo(() => {
    const nextIndex = watchlists.length + 1;
    return `${DEFAULT_WATCHLIST_PREFIX} ${nextIndex}`;
  }, [watchlists.length]);

  function handleAddWatchlist() {
    const trimmed = newWatchlistName.trim();
    onAddWatchlist(trimmed || nextDefaultWatchlistName);
    setNewWatchlistName("");
  }

  function handleRenameWatchlist() {
    if (!activeWatchlist) return;
    const trimmed = renameValue.trim();
    if (!trimmed) return;
    onRenameWatchlist(activeWatchlist.id, trimmed);
  }

  function handleAddSymbol() {
    if (!activeWatchlist) return;
    const trimmed = newSymbol.trim().toUpperCase();
    if (!trimmed) return;
    onAddSymbol(activeWatchlist.id, trimmed);
    setNewSymbol("");
  }

  return (
    <section className="panel watchlist-panel">
      <div className="panel-header">
        <h3>Watchlists</h3>
        <span className="watchlist-count">
          {activeWatchlist?.symbols.length ?? 0} items
        </span>
      </div>

      <div className="watchlist-tabs" role="tablist">
        {watchlists.map((list) => (
          <button
            key={list.id}
            type="button"
            className={`watchlist-tab ${
              list.id === activeWatchlistId ? "active" : ""
            }`}
            onClick={() => onSwitchWatchlist(list.id)}
          >
            {list.name}
          </button>
        ))}
      </div>

      <div className="watchlist-actions">
        <div className="watchlist-field">
          <input
            type="text"
            placeholder="New watchlist name"
            value={newWatchlistName}
            onChange={(event) => setNewWatchlistName(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter") handleAddWatchlist();
            }}
          />
          <button type="button" onClick={handleAddWatchlist}>
            Add
          </button>
        </div>

        <div className="watchlist-field">
          <input
            type="text"
            placeholder="Rename active watchlist"
            value={renameValue}
            onChange={(event) => setRenameValue(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter") handleRenameWatchlist();
            }}
          />
          <button type="button" onClick={handleRenameWatchlist}>
            Rename
          </button>
        </div>

        <div className="watchlist-field">
          <input
            type="text"
            placeholder="Add symbol (e.g., HDFCBANK)"
            value={newSymbol}
            onChange={(event) => setNewSymbol(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter") handleAddSymbol();
            }}
          />
          <button type="button" onClick={handleAddSymbol}>
            Add
          </button>
        </div>
      </div>

      <div className="watchlist-table">
        <div className="stock-table">
          <div className="table-row header">
            <span>Symbol</span>
            <span>Last</span>
            <span>Change</span>
            <span>Trend</span>
            <span></span>
          </div>

          {filteredSymbols.map((symbol) => {
            const stock = getStockBySymbol(symbol);
            const trend = getTrend(stock.change);
            const isSelected = selectedSymbol === symbol;
            return (
              <button
                key={symbol}
                type="button"
                className={`table-row data ${isSelected ? "selected" : ""}`}
                onClick={() => onSelectSymbol(symbol)}
              >
                <span className="symbol">{symbol}</span>
                <span>₹{formatNumber(stock.price)}</span>
                <span className={`change ${trend}`}>
                  {formatChange(stock.change)}
                </span>
                <span className={`trend ${trend}`}>
                  {trend === "up" ? "↑" : "↓"} {trend === "up" ? "Bullish" : "Bearish"}
                </span>
                <span className="row-actions">
                  <button
                    type="button"
                    className="icon-btn"
                    onClick={(event) => {
                      event.stopPropagation();
                      onRemoveSymbol(activeWatchlistId, symbol);
                    }}
                    aria-label={`Remove ${symbol}`}
                  >
                    ✕
                  </button>
                </span>
              </button>
            );
          })}
        </div>
      </div>
    </section>
  );
}
